async ({ git: { commit, push }, shell: { exec } }) => {
  const lock = await exec("ls .git/index.lock 2>&1; pgrep -fa 'git commit' | head -3", {});
  const c = await commit(["-m", `fix: stop a pi-action run that the agent starts inside a run

In run 43520110827 the agent ran node src/index.ts from pit's shell. The
child inherited the step's environment and ran the action again on the
same thread: it moved refs/pi-action/threads/66 under the outer run, whose
storage was then poisoned, and the run failed.

pi-action now sets PI_ACTION_RUNNING (its process ID) in its own
environment at startup, which every tool and child process inherits.
src/index.ts fails at once when it is set, before it reads inputs or
touches a ref; src/push.ts pushes nothing.`], { timeoutMs: 280000 });
  if (c.code !== 0) return { lock: lock.stdout, c: (c.stdout + c.stderr).slice(-2000) };
  const p = await push(["-u", "origin", "fix/nested-run-guard"], { timeoutMs: 280000 });
  return { lock: lock.stdout, c: c.stdout.slice(-400), p: p.code, pout: (p.stdout + p.stderr).slice(-600) };
}
